// Package gen 实现 appkit gen 的四个代码生成器：
// contract（契约五件套：接口/DTO/wrapper/client/server + openapi 派生导出）、
// events（事件类型）、errors（错误码）、wrap（契约 wrapper，ProvideContract 闭环）。
//
// 共同约定：生成物首行是标准 "Code generated" 头；输出前经 go/format 格式化；
// 同一输入重复生成逐字节稳定（golden 测试可校验，CI 用 git diff 防手改）。
package gen

import (
	"fmt"
	"go/format"
	"os"
	"regexp"
	"strings"
)

// header 是生成文件的标准头，匹配 Go 工具链约定的机器可识别格式。
const header = "// Code generated by appkit gen. DO NOT EDIT.\n\n"

// rePackage 同时约束 yaml 里的 package 与 wrap 的 system 名。
var rePackage = regexp.MustCompile(`^[a-z][a-z0-9]*$`)

// writeGo 格式化并写出生成的 Go 源码。格式化失败说明生成器自身有 bug。
func writeGo(outPath string, src []byte) error {
	formatted, err := format.Source(src)
	if err != nil {
		return fmt.Errorf("格式化生成代码失败（生成器 bug，目标 %s）: %w", outPath, err)
	}
	if err := os.WriteFile(outPath, formatted, 0o644); err != nil {
		return fmt.Errorf("写出 %s: %w", outPath, err)
	}
	return nil
}

// initialisms 是导出名转换时保持全大写的常见缩写。
var initialisms = map[string]string{
	"id": "ID", "uid": "UID", "uuid": "UUID",
	"api": "API", "url": "URL", "uri": "URI",
	"http": "HTTP", "sql": "SQL", "json": "JSON", "ip": "IP",
}

// camel 把 snake_case / SCREAMING_SNAKE_CASE 转为导出 CamelCase（entry_id → EntryID）。
func camel(s string) string {
	var b strings.Builder
	for _, p := range strings.Split(strings.ToLower(s), "_") {
		if p == "" {
			continue
		}
		if u, ok := initialisms[p]; ok {
			b.WriteString(u)
			continue
		}
		b.WriteString(strings.ToUpper(p[:1]))
		b.WriteString(p[1:])
	}
	return b.String()
}
